<?php
$banks = rows("SELECT * FROM bank_accounts ORDER BY id"); foreach ($banks as &$b) $b['bal'] = bank_balance((int)$b['id']);
echo '<div class="cols">' . ui_card('حساب‌های بانکی', ui_table(['title' => 'عنوان', 'bank' => 'بانک', 'iban' => ['شبا', 'code'], 'bal' => ['مانده (از سندها)', 'money']], $banks) . ui_form('bank_save', ['title' => ['عنوان', 'text', 1], 'bank' => ['بانک', 'text'], 'iban' => ['شبا (IR…)', 'text'], 'card_no' => ['شمارهٔ کارت', 'text'], 'account_no' => ['شمارهٔ حساب', 'text'], 'owner' => ['صاحبِ حساب', 'text']], [], ['submit' => 'افزودنِ حساب']));
$cbs = cashbox_list(); foreach ($cbs as &$c) $c['bal'] = cashbox_balance((int)$c['id']);
echo ui_card('صندوق‌ها', ui_table(['branch' => 'شعبه', 'name' => 'صندوق', 'bal' => ['مانده (از سندها)', 'money']], $cbs));
$bo = array_column($banks, 'title', 'id');
echo ui_card('تطبیقِ بانک', ui_form('bank_reconcile', ['bank_account_id' => ['حساب', 'select', 1, $bo], 'd' => ['تا تاریخ', 'date', 1], 'statement' => ['ماندهٔ صورت‌حسابِ بانک', 'money', 1], 'note' => ['یادداشت', 'text']], [], ['then' => 'reload'])
    . ui_table(['d' => ['تاریخ', 'date'], 'statement_balance' => ['بانک', 'money'], 'book_balance' => ['دفتر', 'money'], 'diff' => ['مغایرت', 'money']], rows("SELECT * FROM bank_reconcile ORDER BY id DESC LIMIT 20")));
echo ui_card('ثبتِ هزینه', ui_form('expense', ['descr' => ['شرح', 'text', 1], 'amount' => ['مبلغ', 'money', 1], 'account_id' => ['سرفصلِ هزینه', 'select', 1, ui_opts("SELECT id, CONCAT(code,' — ',name) name FROM accounts WHERE kind='expense' AND level<>'group'")], 'method' => ['از', 'select', 1, ['bank' => 'بانک', 'cash' => 'صندوق']], 'bank_account_id' => ['حساب', 'select', 0, $bo], 'd' => ['تاریخ', 'date']])) . '</div>';
echo ui_card('چک‌ها', ui_form('cheque_save', ['direction' => ['نوع', 'select', 1, ['in' => 'دریافتنی', 'out' => 'پرداختنی']], 'number' => ['شماره', 'text', 1], 'bank' => ['بانک', 'text'], 'amount' => ['مبلغ', 'money', 1], 'due' => ['سررسید', 'date', 1], 'party_name' => ['طرف', 'text'], 'bank_account_id' => ['حسابِ ما', 'select', 0, $bo]], [], ['submit' => 'ثبتِ چک'])
    . ui_table(['direction' => ['نوع', fn($r) => $r['direction'] === 'in' ? 'دریافتنی' : 'پرداختنی'], 'number' => ['شماره', 'num'], 'amount' => ['مبلغ', 'money'], 'due_date' => ['سررسید', 'date'], 'party_name' => 'طرف', 'status' => ['وضعیت', fn($r) => ui_badge(['pending' => 'در جریان', 'cleared' => 'وصول‌شده', 'bounced' => 'برگشتی', 'returned' => 'عودت'][$r['status']] ?? $r['status'])],
        'a' => ['', fn($r) => $r['status'] === 'pending' ? ui_btn_api('وصول', 'cheque_status', ['id' => $r['id'], 'status' => 'cleared'], ['class' => 'sm', 'confirm' => 'وصول شد؟']) . ' ' . ui_btn_api('برگشت', 'cheque_status', ['id' => $r['id'], 'status' => 'bounced'], ['class' => 'sm danger']) : '']], rows("SELECT * FROM cheques ORDER BY due_date DESC LIMIT 200")));
